    ('f967e3c4-fc5b-4cd0-91d1-06030d51e31c'::uuid, 'scope_status', NULL, 'retired', 'dup-retire:f967e3c4-fc5b-4cd0-91d1-06030d51e31c:scope_status', 'dup-retire (o9-duplicate-retire): scope_status NULL -> ''retired'' (owner decision O9, B1-D: Shaduppum is the ancient name and Tell Harmal / Tel Hermal the modern name of one tell in Baghdad: the one item and the one Wikipedia title, 20 m apart (B1-D''s ''1,7 km'' is not what production holds: Wikipedia''s point 33.309483, 44.467065 is the survivor''s stored point). The survivor holds 5 content links and 1 citation, the retired row 0 and 0; the retired row''s longer text (Gilgamesh tablets, the Laws of Eshnunna) is not merged here)', 'Shaduppum | content links 0, images 2 | enwiki_title=Shaduppum, wikidata_qid=Q3481186 | survivor Tel Hermal Fort | enwiki_title=Shaduppum, wikidata_qid=Q3481186', '[{"source": "output/remediation/HUMAN_ONLY_DECISIONS_2026-09-26.md", "url": null, "quote": "B1-D: Belegt die Lesung eine einzige Stätte, wird der Verlierer `retired` (`duplicate_of:<uuid>`). Nichts wird gelöscht."}, {"source": "en.wikipedia.org, article ''Shaduppum'' (read 2026-10-01 through the public MediaWiki and Wikidata APIs)", "url": "https://en.wikipedia.org/wiki/Shaduppum", "quote": "Shaduppum (Šaduppȗm), modern Tell Harmal (also Tell Abu Harmal and Tel Harmal), is an archaeological site in Baghdad Governorate (Iraq). Nowadays, it lies within the borders of modern Baghdad about 600 meters from the site of Tell Muhammad"}, {"source": "en.wikipedia.org, article ''Shaduppum'' (read 2026-10-01 through the public MediaWiki and Wikidata APIs)", "url": "https://en.wikipedia.org/wiki/Shaduppum", "quote": "The site, 150 meters in diameter and 5 meters high. Tell Harmal consists of a heavily fortified irregular rectangle"}, {"source": "wikidata:Q3481186 (read 2026-10-01 through the public MediaWiki and Wikidata APIs)", "url": "https://www.wikidata.org/wiki/Q3481186", "quote": "label ''Shaduppum'', description ''Archaeological site in Baghdad'', alias ''Tell Harmal'', enwiki sitelink ''Shaduppum''; Wikipedia''s coordinates are 33.309483, 44.467065"}, {"source": "production:unified_sites.description", "url": null, "quote": "''Shaduppum'': Shaduppum (modern Tell Harmal) was an administrative center in the kingdom of Eshnunna. ''Tel Hermal Fort'': Tel Hermal (ancient Shaduppum) is an Old Babylonian site in present-day Baghdad"}, {"source": "production:site_external_ids", "url": null, "quote": "both rows carry wikidata_qid=Q3481186 and enwiki_title=Shaduppum; 20.3 m apart (read 2026-10-01 17:48:37.993399+00)"}, {"source": "survivor rule", "url": "scripts/remediation/mechanical/scope.py:survivor_rank", "quote": "older row, then more content links, description citations, images, then the lower id: survivor ''Tel Hermal Fort'' (0d8af59c-71cb-4ff6-9620-3eb1faf2ebd3): created 2026-03-04 21:07:57.660461, 5 content link(s), 1 citation(s), 2 image(s) over ''Shaduppum'' (f967e3c4-fc5b-4cd0-91d1-06030d51e31c): created 2026-03-04 21:07:57.660461, 0 content link(s), 0 citation(s), 2 image(s)"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 10;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _dup_retire_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'O9 duplicate retirement: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _dup_retire_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'scope_status' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.new_value IS NULL
                WHEN 'scope_reason' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.new_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'O9 duplicate retirement: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _dup_retire_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN u.scope_status IS DISTINCT FROM p.old_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'O9 duplicate retirement: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row writes a value this lane owns (new value)
    SELECT count(*) INTO bad FROM _dup_retire_plan p
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN p.new_value NOT IN ('retired')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'O9 duplicate retirement: % planned row(s) write a value this lane does not own', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _dup_retire_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (u.name || ' | ' || 'content links ' || CAST((SELECT count(*) FROM site_content_links c WHERE c.site_id = u.id) AS text) || ', images ' || CAST((SELECT count(*) FROM wiki_images w WHERE w.site_id = u.id) AS text) || ' | ' || coalesce((SELECT string_agg(e.kind || '=' || e.value, ', ' ORDER BY e.kind, e.value) FROM site_external_ids e WHERE e.site_id = u.id), '') || ' | survivor ' || coalesce((SELECT s.name || ' | ' || coalesce((SELECT string_agg(e.kind || '=' || e.value, ', ' ORDER BY e.kind, e.value) FROM site_external_ids e WHERE e.site_id = s.id), '') FROM unified_sites s WHERE CAST(s.id AS text) = CASE CAST(u.id AS text) WHEN 'ae2ca7b1-89da-46cb-8924-f9d04dd5da2e' THEN 'ce7db300-8777-425d-917a-2f6d9f325b58' WHEN '3ebb514f-ac4a-4913-b54b-409bcc29eff4' THEN '51daf6c9-25d3-4818-8857-0543f1203c57' WHEN 'dafc7527-c6c8-45c3-8c7d-4813d20a4dcf' THEN 'd41368ba-6aa2-4b75-adf4-8f2cd3cc7e4d' WHEN 'f23a31c3-6833-4df6-8583-3b3930b5a74f' THEN '21ac323f-7214-4891-9499-74e55c3d7d56' WHEN 'f967e3c4-fc5b-4cd0-91d1-06030d51e31c' THEN '0d8af59c-71cb-4ff6-9620-3eb1faf2ebd3' END), '')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'O9 duplicate retirement: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _dup_retire_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'O9/duplicate-retire', '2026-10-01_mechanical-dup-retire', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'O9 duplicate retirement: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _dup_retire_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN u.scope_status IS DISTINCT FROM p.new_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'O9 duplicate retirement: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _dup_retire_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-10-01_mechanical-dup-retire'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'O9 duplicate retirement: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-10-01_mechanical-dup-retire'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('scope_status', 'scope_reason'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'O9 duplicate retirement: this run stamp journalled % row(s) outside unified_sites.(scope_status, scope_reason)', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) name no curated site as their survivor
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _dup_retire_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE NOT EXISTS (SELECT 1 FROM unified_sites s WHERE u.scope_reason = 'duplicate_of:' || CAST(s.id AS text) AND s.source_id = 'ancient_nerds');
    IF bad > 0 THEN
        RAISE EXCEPTION 'O9 duplicate retirement: % planned site(s) name no curated site as their survivor', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) name a retired site as their survivor
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _dup_retire_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE EXISTS (SELECT 1 FROM unified_sites s WHERE u.scope_reason = 'duplicate_of:' || CAST(s.id AS text) AND s.source_id = 'ancient_nerds' AND s.scope_status = 'retired');
    IF bad > 0 THEN
        RAISE EXCEPTION 'O9 duplicate retirement: % planned site(s) name a retired site as their survivor', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) name a survivor further than 2000 m
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _dup_retire_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE EXISTS (SELECT 1 FROM unified_sites s WHERE u.scope_reason = 'duplicate_of:' || CAST(s.id AS text) AND s.source_id = 'ancient_nerds' AND s.scope_status IS DISTINCT FROM 'retired' AND ST_DistanceSphere(ST_MakePoint(s.lon, s.lat), ST_MakePoint(u.lon, u.lat)) > 2000);
    IF bad > 0 THEN
        RAISE EXCEPTION 'O9 duplicate retirement: % planned site(s) name a survivor further than 2000 m', bad;
    END IF;

    RAISE NOTICE 'O9 duplicate retirement: % of % planned cell(s) changed and journalled over 5 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-10-01_mechanical-dup-retire'
UNION ALL
SELECT 'curated rows retired as a duplicate', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND scope_status = 'retired' AND scope_reason LIKE 'duplicate_of:%'
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_dup_retire_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _dup_retire_plan left behind',
       (to_regclass('pg_temp._dup_retire_plan') IS NOT NULL)::int::text
